<script setup lang="ts">
import {computed,ref,watch,onMounted,onBeforeUnmount,nextTick} from 'vue'
import cropProductImage from '@/assets/postharvest/crop-products-v1.png'
import {transportState as transportStock,useTransport} from '@/api/transport'
import QRCode from 'qrcode'
import AgentIcon from '@/components/assistant/AgentIcon.vue'
import {fetchOperations,createOperation,advanceBatch,fetchBatchTrace,type OperationRecord} from '@/api/dashboard'
import type {DashboardSnapshot} from '@/types'
const props=defineProps<{snapshot:DashboardSnapshot;initialBatch?:number}>()
const emit=defineEmits<{(e:'close'):void;(e:'ask',question:string):void}>()
const tabs=[{id:'overview',label:'采后总览'},{id:'harvest',label:'采收管理'},{id:'sorting',label:'分选加工'},{id:'storage',label:'贮藏管理'},{id:'trace',label:'品质追溯'},{id:'loss',label:'损耗分析'}]
const imageRoot=import.meta.env.BASE_URL+'images/postharvest/'
const stageIndex=(stage:string)=>['HARVESTED','SORTED','STORED','DISPATCHED'].indexOf(stage)
const labels:Record<string,string>={HARVESTED:'已采收',SORTED:'已分选',STORED:'贮藏中',DISPATCHED:'已出库'}
const next:Record<string,string>={HARVESTED:'SORTED',SORTED:'STORED',STORED:'DISPATCHED'}
const tab=ref(props.initialBatch?'trace':'overview'),records=ref<OperationRecord[]>([]),selected=ref<number|undefined>(props.initialBatch),trace=ref<OperationRecord[]>([]),error=ref(''),notice=ref(''),busy=ref(false),panel=ref<HTMLElement>()
const plot=ref(props.snapshot.zones[0]?.entityId||''),title=ref(''),quantity=ref<number>(),unit=ref('kg'),note=ref(''),stageNote=ref(''),lossQuantity=ref<number>(),lossReason=ref('机械损伤'),warehouse=ref('演示冷库 01'),temperature=ref<number>(0.5),humidity=ref<number>(90)
const batches=computed(()=>records.value.filter(r=>r.kind==='BATCH'))
const cropKey=(crop:string)=>crop.includes('梨')?'pear':crop.includes('枣')?'jujube':crop.includes('麦')?'wheat':crop.includes('蔬菜')||crop.includes('番茄')||crop.includes('黄瓜')?'vegetable':'other'
const cropFor=(id:string)=>props.snapshot.zones.find(z=>z.entityId===id)?.crop||'其他作物'
const cropCards=computed(()=>[
 {key:'pear',name:'泊头鸭梨',position:'0% 0%'},
 {key:'jujube',name:'金丝小枣',position:'100% 0%'},
 {key:'wheat',name:'旱碱麦',position:'0% 100%'},
 {key:'vegetable',name:'设施蔬菜',position:'100% 100%'}
].map(c=>{const rows=batches.value.filter(b=>cropKey(cropFor(b.entityId))===c.key);const quantities:Record<string,number>={};for(const b of rows)quantities[b.unit||'未登记单位']=(quantities[b.unit||'未登记单位']||0)+(b.quantity||0);return {...c,rows,quantity:Object.entries(quantities).map(([u,n])=>`${n.toLocaleString('zh-CN')} ${u}`).join(' / '),stored:rows.filter(b=>b.stage==='STORED').length}}))
const current=computed(()=>batches.value.find(b=>b.id===selected.value))
const name=(id:string)=>props.snapshot.entities.find(e=>e.id===id)?.name||id
const totals=computed(()=>{const result:Record<string,number>={};for(const b of batches.value)result[b.unit||'未填单位']=(result[b.unit||'未填单位']||0)+(b.quantity||0);return Object.entries(result).map(([u,n])=>`${n.toLocaleString('zh-CN')} ${u}`).join(' / ')||'尚未登记'})
const losses=computed(()=>records.value.filter(r=>r.kind==='AGRONOMY'&&r.title==='采后损耗登记').flatMap(r=>{try{const v=JSON.parse(r.detail);return v.type==='postharvest_loss'?[{...v,id:r.id,createdAt:r.createdAt}]:[]}catch{return []}}))
const currentLosses=computed(()=>losses.value.filter(l=>l.batchId===current.value?.id))
const lossTotal=computed(()=>currentLosses.value.reduce((s,l)=>s+Number(l.quantity||0),0))
const lossRate=computed(()=>current.value?.quantity?Math.round(lossTotal.value/current.value.quantity*1000)/10:0)
function detailText(detail:string){try{const d=JSON.parse(detail);return [d.note,d.warehouse,d.temperature!=null?`温度 ${d.temperature}°C`:null,d.humidity!=null?`湿度 ${d.humidity}%`:null].filter(Boolean).join(' · ')||detail}catch{return detail}}
const storageDetails=computed(()=>{const event=trace.value.find(r=>r.stage==='STORED');if(!event)return null;try{return JSON.parse(event.detail)}catch{return null}})
const gradeDetails=computed(()=>{const event=trace.value.find(r=>r.stage==='SORTED');if(!event)return null;try{return JSON.parse(event.detail).grades||null}catch{return null}})
const qrImage=ref('')
const traceUrl=computed(()=>{if(!current.value)return '';const url=new URL(window.location.href);url.search='';url.searchParams.set('postharvest','trace');url.searchParams.set('batch',String(current.value.id));return url.toString()})
let qrGeneration=0
watch(traceUrl,async url=>{const generation=++qrGeneration;qrImage.value='';if(!url)return;try{const image=await QRCode.toDataURL(url,{width:256,margin:3,errorCorrectionLevel:'M',color:{dark:'#243f36',light:'#ffffff'}});if(generation===qrGeneration)qrImage.value=image}catch{error.value='追溯二维码生成失败，请重试。'}},{immediate:true})
function downloadQr(){if(!qrImage.value||!current.value)return;const a=document.createElement('a');a.href=qrImage.value;a.download=`盐田丰语-追溯码-${current.value.id}.png`;a.click()}
async function load(){try{records.value=await fetchOperations(props.snapshot.farmId);if(!batches.value.some(b=>b.id===selected.value))selected.value=batches.value[0]?.id;if(current.value)await select(current.value.id)}catch(e){error.value=(e as Error).message}}
async function select(id:number){selected.value=id;trace.value=[];try{const rows=await fetchBatchTrace(id,props.snapshot.farmId);if(selected.value===id)trace.value=rows}catch(e){error.value=(e as Error).message}}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function create(){if(!title.value.trim()||!note.value.trim()||!quantity.value||quantity.value<=0){error.value='请填写批次名称、有效数量及采收说明。';return}await action(async()=>{const row=await createOperation({kind:'BATCH',entityId:plot.value,title:title.value.trim(),detail:note.value.trim(),quantity:quantity.value,unit:unit.value},props.snapshot.farmId);selected.value=row.id;title.value='';note.value='';quantity.value=undefined;notice.value='采收批次已登记。'})}
async function advance(){if(!current.value||!next[current.value.stage]||!stageNote.value.trim()){error.value='请填写本次流转说明。';return}if(next[current.value.stage]==='STORED'&&(!warehouse.value.trim()||!Number.isFinite(temperature.value)||!Number.isFinite(humidity.value)||humidity.value<0||humidity.value>100)){error.value='请填写冷库名称、有效温度和 0–100% 湿度。';return}const row=current.value;await action(async()=>{const detail=next[row.stage]==='STORED'?JSON.stringify({warehouse:warehouse.value,temperature:temperature.value,humidity:humidity.value,note:stageNote.value,simulated:true}):stageNote.value.trim();await advanceBatch(row.id,next[row.stage],detail,props.snapshot.farmId);stageNote.value='';notice.value='批次流转已保存，属于软件操作记录。'})}
async function saveLoss(){if(!current.value||!lossQuantity.value||lossQuantity.value<=0||lossTotal.value+lossQuantity.value>(current.value.quantity||0)){error.value='损耗数量须大于 0，累计不得超过批次数量。';return}await action(async()=>{await createOperation({kind:'AGRONOMY',entityId:current.value!.entityId,title:'采后损耗登记',detail:JSON.stringify({type:'postharvest_loss',batchId:current.value!.id,quantity:lossQuantity.value,unit:current.value!.unit,reason:lossReason.value})},props.snapshot.farmId);lossQuantity.value=undefined;notice.value='损耗登记已保存。'})}
function download(){if(!current.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify({batch:current.value,trace:trace.value,losses:currentLosses.value},null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`采后追溯-${current.value.id}.json`;link.click();URL.revokeObjectURL(url)}
function analyze(){emit('ask',`检索${current.value?name(current.value.entityId):props.snapshot.farmName}的采后分选、贮藏及减损资料，读取现有批次，列出适用条件。未记录损耗不能当作零损耗，不编造销售、品质或设备数据。`)}
let releaseTransport=()=>{}
const previous=document.activeElement as HTMLElement|null
function key(e:KeyboardEvent){if(e.key==='Escape'){emit('close');return}if(e.key!=='Tab')return;const list=Array.from(panel.value?.querySelectorAll<HTMLElement>('button:not([disabled]),select,input,textarea')||[]).filter(el=>el.offsetParent!==null);if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0]?.focus()}}
function escape(e:KeyboardEvent){if(e.key==='Escape')emit('close')}
onMounted(async()=>{if(props.snapshot.farmId==='yantian-01')releaseTransport=useTransport();window.addEventListener('keydown',escape);await nextTick();panel.value?.focus();load()});onBeforeUnmount(()=>{releaseTransport();window.removeEventListener('keydown',escape);if(previous?.isConnected)previous.focus()})
</script>
<template><Teleport to="body"><div class="risk-backdrop" @click.self="emit('close')"><section ref="panel" class="risk-center" role="dialog" aria-modal="true" aria-label="采后管理中心" tabindex="-1" @keydown="key"><header><div><small>盐田丰语 · 从采收到出库</small><h1>采后管理中心 <span>软件管理</span></h1></div><button aria-label="关闭采后管理" @click="emit('close')"><AgentIcon name="close" :size="20"/></button></header><div class="risk-layout"><aside><div class="risk-brand"><AgentIcon name="leaf" :size="23"/><span>让每一份收获有记录<small>采收 · 分选 · 贮藏 · 追溯</small></span></div><nav aria-label="采后管理页面"><button v-for="item in tabs" :key="item.id" :aria-pressed="tab===item.id" :class="{active:tab===item.id}" @click="tab=item.id"><AgentIcon :name="item.id==='trace'?'book':'leaf'" :size="17"/>{{item.label}}<span>›</span></button></nav><div class="sidebar-foot">批次记录保存在服务器<br/>设施状态与环境为软件录入</div></aside><main><div class="risk-heading"><div><small>{{tabs.find(t=>t.id===tab)?.label}}</small><h2>{{tab==='overview'?'全链条采后管理':current?.title||'选择或登记一个批次'}}</h2></div><div class="risk-controls"><select :value="selected" aria-label="采后管理批次" @change="select(Number(($event.target as HTMLSelectElement).value))"><option v-if="!batches.length" value="">暂无批次</option><option v-for="batch in batches" :key="batch.id" :value="batch.id">{{batch.title}}</option></select><button :disabled="busy" @click="load">刷新记录</button></div></div><p v-if="error" role="alert" class="risk-error">{{error}}</p><p v-if="notice" role="status" class="risk-notice">{{notice}}</p>

<template v-if="tab==='overview'"><section class="crop-inventory" aria-label="各作物采后库存"><button v-for="crop in cropCards" :key="crop.key" class="crop-inventory-card" :disabled="!crop.rows.length" @click="select(crop.rows[0].id);tab='harvest'"><span class="crop-product-image" role="img" :aria-label="crop.name+'品种示意图'" :style="{backgroundImage:`url(${cropProductImage})`,backgroundPosition:crop.position}"/><span class="crop-inventory-copy"><strong>{{crop.name}}</strong><b>{{crop.quantity||'尚未登记'}}</b><small>{{crop.rows.length}} 个批次 <span>· {{crop.stored}} 批贮藏中</span></small></span><span v-if="crop.rows.length" class="crop-card-arrow">↗</span></button></section><p class="crop-images-note">作物品种示意 · AI 生成图片；数量按登记单位显示。</p><div class="risk-stats"><div><small>采收批次</small><strong>{{batches.length}}<em>批</em></strong><span>当前服务器记录</span></div><div><small>累计采收</small><strong class="quantity-total">{{totals}}</strong><span>按单位分别统计</span></div><div><small>贮藏中</small><strong>{{batches.filter(b=>b.stage==='STORED').length}}<em>批</em></strong><span>已登记入库</span></div><div><small>已出库</small><strong>{{batches.filter(b=>b.stage==='DISPATCHED').length}}<em>批</em></strong><span>出库不等同销售</span></div></div><div class="risk-columns"><section class="risk-card"><h3>各作物采后进度</h3><button v-for="batch in batches" :key="batch.id" class="risk-row" @click="select(batch.id);tab='harvest'"><span v-if="cropCards.some(c=>c.key===cropKey(cropFor(batch.entityId)))" class="crop-product-image batch-product" role="img" :aria-label="cropFor(batch.entityId)+'示意图'" :style="{backgroundImage:`url(${cropProductImage})`,backgroundPosition:cropCards.find(c=>c.key===cropKey(cropFor(batch.entityId)))?.position}"/><div class="batch-copy"><strong>{{batch.title}}</strong><small>{{name(batch.entityId)}} · {{batch.quantity}} {{batch.unit}}</small><div class="batch-progress" aria-label="批次流转进度"><i v-for="i in 4" :key="i" :class="{complete:i<=stageIndex(batch.stage)+1}"/></div></div><span>{{labels[batch.stage]}} ↗</span></button><div v-if="!batches.length" class="empty">暂无采收批次，先登记第一批收获。</div><button class="primary" @click="tab='harvest'">登记采收批次</button></section><section class="risk-card"><h3>最近采后任务</h3><article v-for="row in records.filter(r=>r.kind==='BATCH_EVENT').slice(0,5)" :key="row.id" class="history-row"><strong>{{row.title}} · {{labels[row.stage]}}</strong><p>{{detailText(row.detail)}}</p><time>{{row.createdAt}}</time></article><div v-if="!records.some(r=>r.kind==='BATCH_EVENT')" class="empty">暂无流转事件</div><button class="text-button" @click="analyze">检索采后管理与减损资料 →</button></section></div></template>
<template v-else-if="tab==='harvest'"><div class="risk-columns"><section class="risk-card"><h3>采收批次登记</h3><label class="form-label">种植地块<select v-model="plot"><option v-for="z in snapshot.zones" :key="z.entityId" :value="z.entityId">{{name(z.entityId)}} · {{z.crop}}</option></select></label><label class="form-label">批次名称<input v-model="title" maxlength="160" placeholder="例如：鸭梨秋季采收第一批"/></label><div class="form-pair"><label class="form-label">采收数量<input v-model.number="quantity" type="number" min="0.01" step="0.01"/></label><label class="form-label">单位<select v-model="unit"><option>kg</option><option>吨</option><option>箱</option></select></label></div><label class="form-label">采收说明<textarea v-model="note" maxlength="2000" rows="4" placeholder="记录采收日期、成熟情况与责任人"/></label><button class="primary" :disabled="busy" @click="create">{{busy?'保存中…':'登记采收批次'}}</button></section><section class="risk-card"><h3>采后关键指标</h3><div class="observation-cards"><article><small>当前批次</small><strong>{{current?.quantity??'—'}} {{current?.unit}}</strong><p>{{current?labels[current.stage]:'尚未登记'}}</p></article><article><small>品种与地块</small><strong>{{current?name(current.entityId):'—'}}</strong><p>采收 → 分选 → 入库 → 出库</p></article></div><p class="caption">未登记预计产量、商品率或平均单果重时，不生成这些指标。</p><button class="text-button" @click="tab='sorting'">查看分选流程 →</button></section></div></template>
<template v-else-if="tab==='sorting'||tab==='storage'"><div class="detail-banner"><div><small>{{tab==='sorting'?'分选加工':'冷库与贮藏'}}</small><h3>{{current?labels[current.stage]:'尚无批次'}}</h3><p>{{current?current.quantity+' '+current.unit+' · '+name(current.entityId):'先在采收管理登记批次'}}</p></div><AgentIcon name="leaf" :size="42"/></div><div class="risk-columns"><section class="risk-card"><h3>{{tab==='sorting'?'分选作业记录':'贮藏条件录入'}}</h3><div v-if="tab==='storage'&&transportStock" class="transport-warehouse"><h3>自动运输入库记录</h3><p v-if="!transportStock.inventory.some(i=>i.location==='warehouse')" class="caption">运输完成并确认卸货后，货物显示在此。</p><div v-for="i in transportStock.inventory.filter(i=>i.location==='warehouse')" :key="i.goods+i.unit"><strong>{{i.goods}}</strong><span>{{i.available}} {{i.unit}} · 已预留 {{i.reserved}} {{i.unit}}</span></div><p class="caption">对应运输任务的交接库存，与采后批次流转分别记账。</p></div><div v-if="tab==='storage'" class="storage-form"><label class="form-label">冷库名称<input v-model="warehouse" maxlength="100"/></label><div class="form-pair"><label class="form-label">录入温度 °C<input v-model.number="temperature" type="number" step="0.1"/></label><label class="form-label">录入湿度 %<input v-model.number="humidity" type="number" min="0" max="100"/></label></div><p class="caption">条件为人工录入示例，只有入库时随事件保存；不是实时传感器读数。</p></div><label class="form-label">流转说明<textarea v-model="stageNote" maxlength="2000" rows="4" :placeholder="tab==='sorting'?'填写分级、质量检查和操作说明':'填写库位、贮藏条件与入出库说明'"/></label><button class="primary" :disabled="busy||!current||!next[current.stage]" @click="advance">{{current&&next[current.stage]?'登记'+labels[next[current.stage]]:'流程已完成或暂无批次'}}</button><p class="caption">严格按采收、分选、入库、出库顺序流转。</p></section><section class="risk-card"><h3>{{tab==='sorting'?'分选与品质核验':'贮藏监测与建议'}}</h3><div v-if="tab==='sorting'&&gradeDetails" class="grade-grid"><div v-for="(label,key) in {premium:'精品级',first:'一级品',second:'二级品',processing:'加工级'}" :key="key"><strong>{{gradeDetails[key]}}%</strong><span>{{label}}</span></div></div><div v-if="tab==='storage'&&storageDetails" class="storage-readings"><strong>{{storageDetails.warehouse}}</strong><div><span><b>{{storageDetails.temperature}}°C</b>录入温度</span><span><b>{{storageDetails.humidity}}%</b>录入湿度</span></div><small>已保存的演示入库条件</small></div><div class="observation-cards"><article><small>当前状态</small><strong>{{current?labels[current.stage]:'无批次'}}</strong><p>{{tab==='sorting'?'等级占比来自分选记录；暂无分选线实时速度与专用模型输出。':'当前没有冷库实时设备遥测，已保存条件可在品质追溯查看。'}}</p></article><article><small>AI 资料辅助</small><strong>核验适用条件与管理建议</strong><p>依据品种、成熟度、贮藏环境及已有记录进行资料分析。</p></article></div><button class="primary" @click="analyze">检索采后管理建议 ↗</button></section></div></template>
<template v-else-if="tab==='trace'"><section class="risk-card"><div class="trace-head"><div><h3>产品全流程追溯</h3><p class="caption">批次编号 {{current?`YT-${snapshot.farmId}-${current.id}`:'—'}}</p></div><button class="text-button" :disabled="!current" @click="download">导出追溯档案 →</button></div><div v-if="current" class="qr-trace-card"><div class="qr-code"><img v-if="qrImage" :src="qrImage" alt="当前批次品质追溯二维码" width="160" height="160"/><small>扫码查看该批次追溯记录</small></div><div class="qr-details"><span class="qr-badge">一批一码</span><strong>{{current.title}}</strong><p>{{name(current.entityId)}} · {{current.quantity}} {{current.unit}} · {{labels[current.stage]}}</p><code>YT-{{snapshot.farmId}}-{{current.id}}</code><div class="qr-actions"><button :disabled="!qrImage" @click="downloadQr">下载二维码</button><a :href="traceUrl" target="_blank" rel="noopener">打开追溯页 ↗</a></div><small>追溯页面需登录。跨设备扫码请使用可访问的局域网或部署域名打开平台后生成。</small></div></div><div class="chain trace-timeline"><span v-for="stage in ['HARVESTED','SORTED','STORED','DISPATCHED']" :key="stage" :class="{done:trace.some(r=>r.stage===stage)}">{{labels[stage]}}</span></div><article v-for="row in trace" :key="row.id" class="history-row"><strong>{{labels[row.stage]}}</strong><p>{{detailText(row.detail)}}</p><time>{{row.createdAt}} · {{row.operatorName||'操作记录'}}</time></article><div v-if="!trace.length" class="empty">选择批次后显示服务器流转记录。</div><p class="caption">目前追溯至出库，不把出库记录当作销售或消费者签收。</p></section></template>
<template v-else><div class="risk-columns"><section class="risk-card"><h3>损耗统计与原因</h3><div class="loss-summary"><div class="loss-donut" :style="{background:`conic-gradient(#b58b57 ${Math.min(100,lossRate)*3.6}deg,#dcebe1 0)`}"><span>{{currentLosses.length?lossRate+'%':'—'}}</span></div><strong>{{currentLosses.length?lossRate+'%':'未登记'}}</strong><span>{{currentLosses.length?lossTotal+' '+current?.unit+' 已登记损耗':'缺少损耗记录，不能视为零损耗'}}</span></div><article v-for="loss in currentLosses" :key="loss.id" class="history-row"><strong>{{loss.reason}} · {{loss.quantity}} {{loss.unit}}</strong><time>{{loss.createdAt}}</time></article><p class="caption">损耗率 = 该批次累计登记损耗 / 采收数量。不同单位不混算。</p><button class="text-button" @click="analyze">检索减损优化方案 →</button></section><section class="risk-card"><h3>登记批次损耗</h3><label class="form-label">损耗数量 · {{current?.unit||'批次单位'}}<input v-model.number="lossQuantity" type="number" min="0.01" step="0.01"/></label><label class="form-label">损耗原因<select v-model="lossReason"><option>机械损伤</option><option>病害腐烂</option><option>贮藏不当</option><option>运输损耗</option><option>其他</option></select></label><button class="primary" :disabled="busy||!current" @click="saveLoss">保存损耗记录</button><p class="caption">按录入记录分析；尚未生成预测减损率或经济效益。</p></section></div></template>
<p class="rule-note">{{snapshot.farmName}} · 采后软件闭环。所有流转均为软件记录，未触发真实设备。</p></main></div></section></div></Teleport></template>
